class RepositoryException extends RuntimeException {
    RepositoryException(String message) { super(message); }
}
class KeyIssueFailedException extends RuntimeException {
    KeyIssueFailedException(String message, Throwable cause) { super(message, cause); }
}

class KeyRepository {
    boolean existsActive(String cardId) {
        System.out.println("    [Repository] existsActive(" + cardId + ")");
        if (cardId.equals("C100")) {
            throw new RepositoryException("DB 接続がタイムアウトしました");
        }
        return cardId.equals("C001");
    }
}

class KeyIssueService {
    private final KeyRepository repository = new KeyRepository();
    String issue(String cardId) {
        System.out.println("  [Service] issue(" + cardId + ")");
        try {
            if (repository.existsActive(cardId)) {
                return "409 重複";
            }
            return "201 発行";
        } catch (RepositoryException e) {
            throw new KeyIssueFailedException("鍵の発行に失敗しました cardId=" + cardId, e);
        }
    }
}

class KeyIssueController {
    private final KeyIssueService service = new KeyIssueService();
    String post(String cardId) {
        System.out.println("[Controller] POST /api/keys cardId=" + cardId);
        return service.issue(cardId);
    }
}

// スタックトレースのうち、自分たちのクラスの行だけを抜き出して表示する
Set<String> mine = Set.of("KeyRepository", "KeyIssueService", "KeyIssueController");
String simpleName(String className) {
    return className.substring(Math.max(className.lastIndexOf('$'), className.lastIndexOf('.')) + 1);
}
void printTrace(Throwable t) {
    String prefix = "";
    while (t != null) {
        System.out.println(prefix + t.getClass().getSimpleName() + ": " + t.getMessage());
        for (StackTraceElement f : t.getStackTrace()) {
            String name = simpleName(f.getClassName());
            if (mine.contains(name)) {
                System.out.println("    at " + name + "." + f.getMethodName());
            }
        }
        prefix = "Caused by: ";
        t = t.getCause();
    }
}

var controller = new KeyIssueController();
System.out.println("結果: " + controller.post("C001"));
System.out.println();
try {
    controller.post("C100");
} catch (RuntimeException e) {
    System.out.println();
    System.out.println("--- スタックトレース(自分のクラスの行だけ) ---");
    printTrace(e);
    Throwable root = e;
    while (root.getCause() != null) {
        root = root.getCause();
    }
    System.out.println("--- 根本原因(一番下の Caused by) ---");
    System.out.println(root.getClass().getSimpleName() + ": " + root.getMessage());
}

