import org.springframework.context.annotation.*;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.annotation.*;
import org.springframework.transaction.support.*;

// DB の代わりに「開始・コミット・ロールバック」を表示するだけのトランザクションマネージャ(読み飛ばしてOK)
class LogTxManager extends AbstractPlatformTransactionManager {
    protected Object doGetTransaction() { return TransactionSynchronizationManager.isActualTransactionActive(); }
    protected boolean isExistingTransaction(Object tx) { return (Boolean) tx; }
    protected void doBegin(Object tx, TransactionDefinition def) { System.out.println("  [TX] 開始"); }
    protected void doCommit(DefaultTransactionStatus s) { System.out.println("  [TX] コミット"); }
    protected void doRollback(DefaultTransactionStatus s) { System.out.println("  [TX] ロールバック"); }
}

@Configuration @EnableTransactionManagement
class TxConfig {
    @Bean LogTxManager transactionManager() { return new LogTxManager(); }
}

class KeyRotationService {
    @Transactional
    public void rotate(String cardId) {
        System.out.println("  [Service] 今の鍵を失効 → HSM に新しい鍵を依頼");
        throw new IllegalStateException("HSM に接続できません cardId=" + cardId);
    }
}

